-- # Lernfeld 5: Cyberphysische Systeme > ## IT-Sicherheit > - Datensicherung > - + Backup

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein Backup allein vor Datenverlust durch Ransomware schützen?', 2, '[{"text": "Nein", "correct": true, "because": "Backup schützt nur durch Wiederherstellung, nicht Prävention"}, {"text": "Ja", "correct": false, "because": "Schutz erfordert zusätzliche Maßnahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein einmaliges Backup ausreichend, um Daten über einen längeren Zeitraum zu sichern?', 2, '[{"text": "Nein", "correct": true, "because": "Änderungen werden nicht erfasst"}, {"text": "Ja", "correct": false, "because": "Regelmäßigkeit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Backups ohne physische Trennung vom Hauptnetzwerk sicher vor Cyberangriffen sein?', 2, '[{"text": "Nein", "correct": true, "because": "Online-Backups sind anfällig"}, {"text": "Ja", "correct": false, "because": "Isolation erhöht Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind inkrementelle Backups immer schneller als vollständige Backups?', 2, '[{"text": "Ja", "correct": true, "because": "Nur Änderungen werden gesichert"}, {"text": "Nein", "correct": false, "because": "Inkrementell ist effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Backup-Strategie ohne Test der Wiederherstellung als zuverlässig gelten?', 2, '[{"text": "Nein", "correct": true, "because": "Ungetestete Backups können fehlerhaft sein"}, {"text": "Ja", "correct": false, "because": "Tests bestätigen Funktionalität"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Backup-Methode sichert ausschließlich geänderte Daten seit dem letzten vollständigen Backup?', 2, '[{"text": "Differentielles Backup", "correct": true, "because": "Vergleicht mit letztem Vollbackup"}, {"text": "Inkrementelles Backup", "correct": false, "because": "Nur seit letztem Backup"}, {"text": "Spiegel-Backup", "correct": false, "because": "Exakte Kopie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strategie wird empfohlen, um Backups vor physischen und digitalen Bedrohungen zu schützen?', 3, '[{"text": "3-2-1-Regel", "correct": true, "because": "3 Kopien, 2 Medien, 1 extern"}, {"text": "Tägliche Spiegelung", "correct": false, "because": "Fehlt Isolation"}, {"text": "Cloud-only Backup", "correct": false, "because": "Ein Medium"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Speicherort ist für ein sicheres Backup am riskantesten?', 2, '[{"text": "Derselbe Server wie die Originaldaten", "correct": true, "because": "Keine Trennung bei Ausfall"}, {"text": "Externe Festplatte", "correct": false, "because": "Physisch getrennt"}, {"text": "Cloud-Speicher", "correct": false, "because": "Geografisch verteilt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptursache für fehlerhafte Backups?', 2, '[{"text": "Fehlende Validierung", "correct": true, "because": "Ungeprüfte Daten unzuverlässig"}, {"text": "Zu häufige Sicherung", "correct": false, "because": "Kein direkter Fehler"}, {"text": "Langsame Internetverbindung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Backup-Technik minimiert den Speicherbedarf bei maximaler Historie?', 2, '[{"text": "Inkrementelles Backup", "correct": true, "because": "Nur Änderungen gesichert"}, {"text": "Vollständiges Backup", "correct": false, "because": "Hoher Speicherbedarf"}, {"text": "Snapshot-Backup", "correct": false, "because": "Statusabbild"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Backup-Typen gibt es in der Praxis?', 4, '[{"text": "Vollständiges Backup", "correct": true, "because": "Komplette Datenkopie"}, {"text": "Inkrementelles Backup", "correct": true, "because": "Nur Änderungen"}, {"text": "Differentielles Backup", "correct": true, "because": "Änderungen seit Vollbackup"}, {"text": "Replikations-Backup", "correct": false, "because": "Keine Backup-Art"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Backup sicher und zuverlässig?', 3, '[{"text": "Regelmäßige Durchführung", "correct": true, "because": "Aktuelle Daten gesichert"}, {"text": "Verschlüsselung", "correct": true, "because": "Schützt vor Zugriff"}, {"text": "Hohe Komprimierung", "correct": false, "because": "Optional, nicht sicherheitsrelevant"}, {"text": "Offsite-Speicherung", "correct": true, "because": "Schützt vor lokalen Ausfällen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken bedrohen die Integrität eines Backups?', 3, '[{"text": "Cyberangriffe", "correct": true, "because": "Können Backup infizieren"}, {"text": "Hardwarefehler", "correct": true, "because": "Medium kann ausfallen"}, {"text": "Zu schnelle Sicherung", "correct": false, "because": "Kein Integritätsrisiko"}, {"text": "Fehlende Tests", "correct": true, "because": "Unentdeckte Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für eine effektive Backup-Strategie essenziell?', 4, '[{"text": "Automatisierung", "correct": true, "because": "Reduziert menschliche Fehler"}, {"text": "Wiederherstellungsplan", "correct": true, "because": "Definiert Vorgehen"}, {"text": "Einmalige Sicherung", "correct": false, "because": "Nicht ausreichend"}, {"text": "Regelmäßige Überprüfung", "correct": true, "because": "Stellt Funktionalität sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Cloud-Backup gegenüber lokalen Backups?', 3, '[{"text": "Geografische Redundanz", "correct": true, "because": "Schutz vor lokalen Katastrophen"}, {"text": "Einfacher Zugriff", "correct": true, "because": "Von überall erreichbar"}, {"text": "Geringere Kosten", "correct": false, "because": "Kosten variieren"}, {"text": "Automatische Hardwarewartung", "correct": true, "because": "Anbieter übernimmt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Vollbackup ist schneller als ein inkrementelles Backup. b) Backups sollten immer verschlüsselt sein.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Vollbackup langsamer, Verschlüsselung empfohlen"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die 3-2-1-Regel fordert zwei Cloud-Backups. b) Ein Backup-Test ist für die Zuverlässigkeit entscheidend.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Regel spezifiziert Medien, Test essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Differentielles Backup benötigt mehr Speicher als inkrementelles. b) Cloud-Backups sind immun gegen Cyberangriffe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Differentiell größer, Cloud angreifbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Backups auf demselben Server sind sicher vor Hardwareausfällen. b) Automatisierte Backups reduzieren menschliche Fehler.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Server unsicher, Automatisierung hilft"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Backup ohne Offsite-Kopie genügt für Katastrophenschutz. b) Inkrementelle Backups erhöhen die Wiederherstellungszeit.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Offsite nötig, Inkrementell komplexer"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

